<script setup>import {money,orderStates,payStates} from '../api/client.js';defineProps(['order']);defineEmits(['close'])</script>
<template><div class="overlay" @click.self="$emit('close')"><section class="modal"><div class="section-title"><h2>订单详情</h2><button @click="$emit('close')">关闭</button></div><p class="muted">{{order.number}}</p><p><span class="badge">{{orderStates[order.status]}}</span> · {{payStates[order.payStatus]}}</p><p>{{order.consignee}} {{order.phone}}</p><p>{{order.address}}</p><p>下单：{{order.orderTime}}<br>支付：{{order.checkoutTime||'—'}}</p><div v-for="d in order.orderDetails" :key="d.id" class="line"><span>{{d.name}} <small>{{d.dishFlavor}}</small> × {{d.number}}</span><b>{{money(Number(d.amount)*d.number)}}</b></div><h3>合计 {{money(order.amount)}}</h3><p>备注：{{order.remark||'无'}}</p><p v-if="order.cancelReason||order.rejectionReason">取消原因：{{order.cancelReason||order.rejectionReason}}</p></section></div></template>
